import{_ as e,o as a,c as n,a2 as r}from"./chunks/framework.CRkDNIZq.js";const p=JSON.parse('{"title":"Security Architecture & OWASP Top 10 Audit","description":"","frontmatter":{},"headers":[],"relativePath":"06-security.md","filePath":"06-security.md"}'),i={name:"06-security.md"};function s(l,t,o,d,c,g){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="security-architecture-owasp-top-10-audit" tabindex="-1">Security Architecture &amp; OWASP Top 10 Audit <a class="header-anchor" href="#security-architecture-owasp-top-10-audit" aria-label="Permalink to &quot;Security Architecture &amp; OWASP Top 10 Audit&quot;">​</a></h1><p>Financial billing platforms are primary targets for credential stuffing, unauthorized balance manipulation, and invoice tampering. This document audits <code>19-usage-billing-engine</code> against the OWASP Top 10.</p><hr><h2 id="owasp-top-10-mapping-defenses" tabindex="-1">OWASP Top 10 Mapping &amp; Defenses <a class="header-anchor" href="#owasp-top-10-mapping-defenses" aria-label="Permalink to &quot;OWASP Top 10 Mapping &amp; Defenses&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Vulnerability</th><th style="text-align:left;">Status in Code</th><th style="text-align:left;">Defense Mechanism Implemented</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>A01: Broken Access Control</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Deny-by-default RBAC (<code>security/auth.py</code>). All database queries explicitly filter by <code>tenant_id</code>, preventing cross-tenant data leakage.</td></tr><tr><td style="text-align:left;"><strong>A02: Cryptographic Failures</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">API keys are hashed with SHA-256 before storage (<code>AuthManager._hash_key</code>); plaintext keys are never persisted.</td></tr><tr><td style="text-align:left;"><strong>A03: Injection</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">SQLAlchemy parameterized queries eliminate SQL injection; Pydantic model validators sanitize inputs.</td></tr><tr><td style="text-align:left;"><strong>A04: Insecure Design</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Double-entry ledger enforces balance conservation; negative quantities rejected at DB schema level.</td></tr><tr><td style="text-align:left;"><strong>A05: Security Misconfiguration</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Debug mode disabled in production; Starlette CORS restricted to authorized billing console origins.</td></tr><tr><td style="text-align:left;"><strong>A06: Vulnerable Components</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Python 3.13 and updated Pydantic v2 libraries scanned via <code>pip-audit</code>.</td></tr><tr><td style="text-align:left;"><strong>A07: Identification &amp; Auth</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Random 32-byte cryptographically secure tokens (<code>secrets.token_urlsafe</code>); revoked keys rejected immediately.</td></tr><tr><td style="text-align:left;"><strong>A08: Software &amp; Data Integrity</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Finalized invoices and ledger transactions are immutable; updates and deletes prohibited.</td></tr><tr><td style="text-align:left;"><strong>A09: Logging &amp; Monitoring</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">Audit logger (<code>security/audit.py</code>) records all mutations, automatically masking PII, Tax IDs, and card numbers.</td></tr><tr><td style="text-align:left;"><strong>A10: SSRF</strong></td><td style="text-align:left;"><strong>Protected</strong></td><td style="text-align:left;">External webhook URLs validated against strict allowlists before dispatch.</td></tr></tbody></table><hr><h2 id="financial-ledger-immutability-anti-tamper-controls" tabindex="-1">Financial Ledger Immutability &amp; Anti-Tamper Controls <a class="header-anchor" href="#financial-ledger-immutability-anti-tamper-controls" aria-label="Permalink to &quot;Financial Ledger Immutability &amp; Anti-Tamper Controls&quot;">​</a></h2><ol><li><strong>Append-Only Enforcement</strong>: The <code>ledger_entries</code> table permits only <code>INSERT</code> statements. Corrections must be submitted as new reversing entries referencing the original transaction.</li><li><strong>Check Constraints</strong>: Schemas enforce <code>amount_cents &gt; 0</code> on ledger entries and <code>quantity &gt;= 0</code> on usage events, preventing negative balance manipulation.</li><li><strong>Automated PII Redaction</strong>: Before any audit record is persisted, <code>redact_sensitive_info()</code> recursively scrubs tax IDs, SSNs, credit card numbers, and passwords using regular expression filters.</li></ol>',8)])])}const y=e(i,[["render",s]]);export{p as __pageData,y as default};
